attributes.onAreaChange:
(_old: Area, area: Area): void => {
          const height = typeof area.height === 'number' ? area.height :
            (typeof area.height === 'string' ? Number.parseFloat(area.height) : 0);
          if (Number.isFinite(height) && height > 0 && Math.abs(height - this.measuredMessageHeight) > 0.5) {
            this.measuredMessageHeight = height;
          }
        }

attributes.linearGradient:
{ angle: 0, colors: this.isFilterSelected(dimension, value) ?
        [[readerAppColor('TOK_PRIMARY_DARK', this.appThemeScheme), 0], [readerAppColor('TOK_PRIMARY_DARK', this.appThemeScheme), 1]] :
        [[Color.Transparent, 0], [Color.Transparent, 1]] }

attributes.onAreaChange:
(_old: Area, area: Area): void => {
          const width = readerPageAreaLength(area.width);
          if (Number.isFinite(width) && width > 0 && Math.abs(width - this.introMeasuredWidth) > .1) {
            this.introMeasuredWidth = width; this.measureIntro();
          }
        }

